begin;
create temp table keep_marks on commit drop as select imported_from,status,rating,notes,share_token,hidden,category from recipes where imported_from in ('tg:280354','tg:252364','drive:sandwiches-1','drive:sandwiches-2','drive:sandwiches-3','drive:sandwiches-4','drive:sandwiches-5','drive:sandwiches-6','drive:sandwiches-7');
delete from recipes where imported_from='tg:280354';
delete from recipes where imported_from='tg:252364';
delete from recipes where imported_from='drive:sandwiches-1';
delete from recipes where imported_from='drive:sandwiches-2';
delete from recipes where imported_from='drive:sandwiches-3';
delete from recipes where imported_from='drive:sandwiches-4';
delete from recipes where imported_from='drive:sandwiches-5';
delete from recipes where imported_from='drive:sandwiches-6';
delete from recipes where imported_from='drive:sandwiches-7';
update recipes r set status=k.status, rating=k.rating, notes=k.notes, share_token=k.share_token, hidden=k.hidden, category=coalesce(k.category, r.category) from keep_marks k where r.imported_from=k.imported_from;
commit;