insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='tg:280354'),0,null,'Картофель и морковь помыть щёткой и отварить в большом количестве воды, 20–25 минут для небольших. Яйца варить 10 минут после закипания, остудить в холодной воде.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='tg:280354'),1,null,'Говядину опустить в кипящую воду (тогда бульон будет чистым) и варить на тихом огне до готовности — от 40 минут до 2 часов в зависимости от куска. Воду не солить. До нарезки держать мясо в бульоне, чтобы не потемнело.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='tg:280354'),2,null,'Нарезать огурец, сложить в миску с горошком.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='tg:280354'),3,null,'Мясо быстро нарезать кубиком, добавить к огурцу с горошком и перемешать — пусть немного замаринуется.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='tg:280354'),4,null,'Очистить и мелко нарезать морковь и картофель, добавить в миску.';
insert into recipe_steps(recipe_id,position,section,text) select (select id from recipes where imported_from='tg:280354'),5,null,'Яйца нарезать кубиком, поперчить, заправить майонезом. Солить по вкусу, ориентируясь на солёность огурцов. Перемешать.';
